{
  "type": "Full-color comic page",
  "genre": "Dark fantasy",
  "style": "High-quality anime illustrations, dramatic lighting and shadows, cinematic composition.",
  "character": {
    "appearance": "{argument name=\"hair color\" default=\"Long white hair\"} Paired with a black ribbon,{argument name=\"eye color\" default=\"Glowing blue eyes\"} Wearing a black gothic coat with a cross-shaped zipper pull"
  },
  "layout": {
    "format": "A vertical comic page containing 7 independent horizontal panels.",
    "panels": [
      {
        "tier": 1,
        "description": "The top panel is large. The character is looking down with their eyes closed.",
        "elements": [
          {
            "type": "title_logo",
            "position": "Top right corner",
            "text": "{argument name=\"main title\" default=\"Re-Birth Log\"}"
          },
          {
            "type": "text_box",
            "position": "Top left corner",
            "text": "{argument name=\"opening text\" default=\"I—I was supposed to be dead.\"}"
          }
        ]
      },
      {
        "tier": 2,
        "description": "Narrow horizontal panel layout. Extreme close-up of the character's glowing eyes.",
        "elements": [
          {
            "type": "text_box",
            "position": "right side",
            "text": "When I woke up, I was in an unfamiliar world."
          }
        ]
      },
      {
        "tier": 3,
        "description": "The montage frames show Gothic castles, roaring dragons, and the backs of characters.",
        "elements": [
          {
            "type": "text_box",
            "position": "Left side",
            "text": "Magic, auras, and—dragons."
          }
        ]
      },
      {
        "tier": 4,
        "description": "The character looks dejected in the dark, desolate forest.",
        "elements": [
          {
            "type": "text_box",
            "position": "Left side",
            "text": "Moreover, despite being a nobleman, this body is considered \"useless.\""
          }
        ]
      },
      {
        "tier": 5,
        "description": "The image is divided into sections. The left side shows a sorrowful profile. The right side shows a close-up of determined, shining eyes.",
        "elements": [
          {
            "type": "text_box",
            "position": "Left side",
            "text": "Powerless. No intelligence. A worthless existence, practically garbage."
          },
          {
            "type": "text_box",
            "position": "Middle right",
            "text": "—That's just what people think."
          }
        ]
      },
      {
        "tier": 6,
        "description": "Abstract magic panel. The left side displays a glowing blue spade symbol within a magic circle. The right side displays a glowing, number-style dialog box.",
        "elements": [
          {
            "type": "text_box",
            "position": "central",
            "text": "A sealed power. And the \"memories\" that remain within me."
          },
          {
            "type": "glowing_text_box",
            "position": "right side",
            "text": "\"Sign the contract.\""
          }
        ]
      },
      {
        "tier": 7,
        "description": "The bottom panel is large. The character looks confidently forward, a cold smile playing on his lips.",
        "elements": [
          {
            "type": "text_box",
            "position": "Top left corner",
            "text": "……いいだろう。"
          },
          {
            "type": "text_box",
            "position": "Middle left",
            "text": "I'm going to use all the cards in this hand."
          },
          {
            "type": "text_box",
            "position": "bottom right corner",
            "text": "{argument name=\"closing text\" default=\"I&#39;m no longer that &quot;Serena.&quot;\"}"
          }
        ]
      }
    ]
  }
}

